"""Hive box reader.

Hive is a key-value store written in Dart, used by Flutter apps as a local
store (github.com/isar/hive, Apache-2.0, continued as
github.com/IO-Design-Team/hive_ce). A box is a flat sequence of
frames with no file header and no magic bytes, so the layout is small enough to
read directly:

    uint32  frame length, little-endian, counting these 4 bytes and the CRC
    uint8   key type: 0 = uint32 key, 1 = UTF-8 key
            uint32 key, or uint8 length then that many bytes of UTF-8
    uint8   value type, then the value, absent entirely on a deletion
    uint32  CRC32 over the frame

A paired ``<box>.lock`` carries no data. A ``<box>.hivec`` is the temporary file
written during compaction.

Three properties matter when reading one of these as evidence.

**The box is append-only.** Writing a key appends a frame rather than editing
the existing one, so a key that has been changed appears more than once and the
earlier frames are superseded values still present in the file. ``read_frames``
returns every frame in file order so those stay visible; ``live_entries``
collapses to the last occurrence, which is the value the app reads.

**A deletion is a frame carrying the key and no value**, not a removal. It is
reported with ``deleted`` set, and ``live_entries`` drops the key, matching what
the app sees. A frame whose value is a stored null is a different thing and is
reported as such.

**History survives longer than you would expect.** By default Hive rewrites a
box only once more than 60 frames have been superseded or deleted *and* that
count exceeds 15% of the live entry count (``box/default_compaction_strategy.dart``
with ``box/keystore.dart``: ``_deletedEntries`` counts an overwrite as well as a
delete, and the ratio is taken against ``keystore.length``, which is the number
of live entries rather than the number of frames). An app can pass its own
strategy or call ``compact()`` itself. Below either threshold nothing is purged,
so a small box can retain its whole history. Nothing in the file records that a
rewrite happened, so this reader never claims one did.

Values at type id 32 and above are developer-defined ``TypeAdapter`` types. An
adapter generated by ``hive_generator`` from ``@HiveType``/``@HiveField`` writes
a field count, then per field an index byte and a type-tagged value, so the
payload describes itself. A hand-written adapter calling the raw writers emits
none of that, and this reader does not decode it: its layout is only in the
app's Dart code. The declared
id is offset by 32 on disk, so ``@HiveType(typeId: 0)`` is written as 32.

Nothing here decrypts. Hive's AES-256-CBC mode encrypts **only values**; keys
stay in the clear, so an encrypted box still yields its key namespace and frame
ordering. Its frame CRC is seeded with a CRC of the key, so every checksum fails
without it. ``read_frames`` reports that as ``looks_encrypted`` rather than as
corruption.

Format read from isar/hive v2.2.3, commit
470473ffc1ba39f6c90f31ababe0ee63b76b69fe:
``binary/frame.dart`` for the type vocabulary, ``binary/binary_reader_impl.dart``
for frame and value parsing, ``crypto/hive_aes_cipher.dart`` for the cipher and
key CRC, ``box/default_compaction_strategy.dart`` for the thresholds, and
``registry/type_registry_impl.dart`` for the 32 offset. The set type ids are
from IO-Design-Team/hive_ce at 8cb526c78b6f.
"""

import struct
import zlib

__version__ = '0.1.0'

__all__ = [
    'HiveObject', 'HiveDateTime', 'HiveSet', 'HiveListRef', 'HiveRaw',
    'HiveError', 'looks_encrypted', 'superseded_counts',
    'read_frames', 'live_entries', 'hive_entries', 'read_value',
    'displaced_counts',
    'type_name', 'RESERVED_TYPE_IDS',
]

# Frame key types, from binary/frame.dart.
KEY_UINT, KEY_UTF8 = 0, 1

# Developer type ids are offset by this on disk, from registry/type_registry_impl.dart.
RESERVED_TYPE_IDS = 32

# A frame longer than this is treated as a bad length rather than honoured, so a
# corrupt uint32 cannot make the reader allocate against the whole file.
_MAX_FRAME = 1 << 20

_TYPE_NAMES = {
    0: 'null', 1: 'int', 2: 'double', 3: 'bool', 4: 'string', 5: 'byteList',
    6: 'intList', 7: 'doubleList', 8: 'boolList', 9: 'stringList',
    10: 'list', 11: 'map', 12: 'hiveList',
    13: 'intSet', 14: 'doubleSet', 15: 'stringSet',
    16: 'DateTime (no zone recorded)', 17: 'BigInt', 18: 'DateTime',
    19: 'set',
}


class HiveError(ValueError):
    """A frame or value that does not parse as the format describes."""


class HiveObject(dict):
    """A value written by a developer-defined TypeAdapter.

    A ``dict`` of ``{field index: value}``, because the field *names* live only
    in the app's compiled Dart. Subclassing ``dict`` keeps ``isinstance(v, dict)``
    and ``v.get(3)`` working for callers, while ``type_id`` and ``declared_id``
    say which adapter wrote it. ``declared_id`` is the id in the app's source,
    which is the on-disk id minus 32.
    """

    __slots__ = ('type_id', 'declared_id')

    def __init__(self, type_id, fields):
        super().__init__(fields)
        self.type_id = type_id
        self.declared_id = type_id - RESERVED_TYPE_IDS

    def __repr__(self):
        return f'HiveObject(typeId={self.type_id}, {dict.__repr__(self)})'


class HiveDateTime(int):
    """Milliseconds since the Unix epoch, as the box stores them.

    An ``int`` so arithmetic and ``int(value)`` work unchanged. ``zone_recorded``
    is False for adapter 16, which stores milliseconds and nothing else: that
    value has no zone to convert from and must not be reported as UTC. Adapter 18
    stores an explicit flag, carried here as ``is_utc``.

    Every Hive 2.x release registers the timezone adapter first and
    ``findAdapterForValue`` returns on the first runtime-type match, so a plain
    Dart ``DateTime`` is always written as 18. A 16 came from an older writer.
    """

    # No __slots__: CPython does not allow a nonempty one on an int subtype.

    def __new__(cls, ms, is_utc=None, zone_recorded=True):
        self = super().__new__(cls, ms)
        self.is_utc = is_utc
        self.zone_recorded = zone_recorded
        return self

    def __repr__(self):
        if not self.zone_recorded:
            return f'HiveDateTime({int(self)}, zone not recorded)'
        return f'HiveDateTime({int(self)}, is_utc={self.is_utc})'


class HiveSet(list):
    """A Dart ``Set``, kept in the order the box stores it.

    hive_ce writes a set with the wire encoding of the matching list type and
    converts on read. Order is preserved here rather than discarded, because the
    stored order is what the file actually records.
    """

    __slots__ = ()

    def __repr__(self):
        return f'HiveSet({list.__repr__(self)})'


class HiveRaw:
    """A developer type whose payload does not describe itself.

    An adapter written by hand calls the raw writers, so the payload carries no
    field count, no field indexes and no type bytes, and nothing can recover its
    fields without the app's compiled Dart. The bytes are kept as they are.

    Deliberately not a ``dict``, so a caller that tells a record from a scalar
    with ``isinstance(value, dict)`` skips this rather than treating an
    undecoded blob as a record.
    """

    __slots__ = ('type_id', 'declared_id', 'payload')

    def __init__(self, type_id, payload):
        self.type_id = type_id
        self.declared_id = type_id - RESERVED_TYPE_IDS
        self.payload = bytes(payload)

    def __len__(self):
        return len(self.payload)

    def __eq__(self, other):
        return (isinstance(other, HiveRaw) and self.type_id == other.type_id
                and self.payload == other.payload)

    def __repr__(self):
        return (f'HiveRaw(typeId={self.type_id}, '
                f'app declared {self.declared_id}, {len(self.payload)} bytes)')


class HiveListRef(list):
    """A reference into another box: a box name and the keys it points at.

    A HiveList is stored as a count, then the length-prefixed name of the box
    the keys belong to, then that many keys (``writeHiveList``). The values themselves live in that
    other box, so this carries the keys only.
    """

    __slots__ = ('box_name',)

    def __init__(self, box_name, keys):
        super().__init__(keys)
        self.box_name = box_name

    def __repr__(self):
        return f'HiveListRef(box={self.box_name!r}, {list.__repr__(self)})'


class _Reader:
    """Bounded cursor over one frame's bytes."""

    __slots__ = ('data', 'offset', 'end')

    def __init__(self, data, offset, end):
        self.data = data
        self.offset = offset
        self.end = end

    @property
    def remaining(self):
        return self.end - self.offset

    def take(self, count):
        if count < 0 or self.offset + count > self.end:
            raise HiveError('frame ended early')
        chunk = self.data[self.offset:self.offset + count]
        self.offset += count
        return chunk

    def uint8(self):
        return self.take(1)[0]

    def uint32(self):
        return struct.unpack('<I', self.take(4))[0]

    def float64(self):
        return struct.unpack('<d', self.take(8))[0]

    def string(self, count=None):
        if count is None:
            count = self.uint32()
        return self.take(count).decode('utf-8', 'replace')

    def key(self):
        key_type = self.uint8()
        if key_type == KEY_UINT:
            return self.uint32()
        if key_type == KEY_UTF8:
            return self.string(self.uint8())
        raise HiveError(f'unsupported key type {key_type}')

    def value(self, type_id=None):
        if type_id is None:
            type_id = self.uint8()

        if type_id == 0:
            return None
        if type_id == 1:
            return int(self.float64())          # an int is stored as a float64
        if type_id == 2:
            return self.float64()
        if type_id == 3:
            return bool(self.uint8())
        if type_id == 4:
            return self.string()
        if type_id == 5:
            return self.take(self.uint32())
        if type_id in (6, 13):
            out = [int(self.float64()) for _ in range(self.uint32())]
            return HiveSet(out) if type_id == 13 else out
        if type_id in (7, 14):
            out = [self.float64() for _ in range(self.uint32())]
            return HiveSet(out) if type_id == 14 else out
        if type_id == 8:
            return [bool(self.uint8()) for _ in range(self.uint32())]
        if type_id in (9, 15):
            out = [self.string() for _ in range(self.uint32())]
            return HiveSet(out) if type_id == 15 else out
        if type_id in (10, 19):
            out = [self.value() for _ in range(self.uint32())]
            return HiveSet(out) if type_id == 19 else out
        if type_id == 11:
            # A map is count PAIRS. Reading count values instead returns half
            # the map and leaves the cursor inside it.
            count = self.uint32()
            out = {}
            for _ in range(count):
                map_key = self.value()
                if isinstance(map_key, (list, dict, set)):
                    map_key = repr(map_key)
                out[map_key] = self.value()
            return out
        if type_id == 12:
            # count, then the length-prefixed name of the box the keys live in,
            # then that many keys. Not a list of values.
            count = self.uint32()
            box_name = self.string(self.uint8())
            return HiveListRef(box_name, [self.key() for _ in range(count)])
        if type_id == 16:
            return HiveDateTime(int(self.float64()), zone_recorded=False)
        if type_id == 17:
            return int(self.string(self.uint8()))
        if type_id == 18:
            ms = int(self.float64())
            return HiveDateTime(ms, is_utc=bool(self.uint8()))
        if type_id < RESERVED_TYPE_IDS:
            raise HiveError(f'reserved type id {type_id} has no known encoding')

        # A developer type. An adapter generated by hive_generator writes a field
        # count, then per field an index byte and a type-tagged value, so the
        # payload describes itself. A hand-written adapter calling the raw
        # writers emits none of that, and walking it anyway yields plausible
        # nonsense, so a walk that does not parse falls back to raw bytes.
        start = self.offset
        try:
            count = self.uint8()
            fields = {}
            for _ in range(count):
                index = self.uint8()
                fields[index] = self.value()
            return HiveObject(type_id, fields)
        except (HiveError, IndexError, struct.error, UnicodeDecodeError):
            self.offset = start
            return HiveRaw(type_id, self.take(self.remaining))


def read_value(buf, index):
    """One value at ``index``, returning it and the index after it.

    Kept for callers written against a reader with this shape.
    """
    reader = _Reader(buf, index, len(buf))
    value = reader.value()
    return value, reader.offset


def type_name(type_id):
    """A readable name for a value type id."""
    if type_id is None:
        return 'none'
    if type_id in _TYPE_NAMES:
        return _TYPE_NAMES[type_id]
    if type_id >= RESERVED_TYPE_IDS:
        return f'custom typeId {type_id} (app declared {type_id - RESERVED_TYPE_IDS})'
    return f'reserved typeId {type_id}'


def _frame_at(data, offset, key_crc):
    """The frame starting at ``offset``, or None if nothing valid starts there.

    A value that does not parse is recorded on its own frame as ``error`` and
    does not stop the walk, so one unreadable value costs that frame rather than
    every frame after it.
    """
    if offset + 8 > len(data):
        return None
    length = struct.unpack_from('<I', data, offset)[0]
    if length < 8 or length > min(_MAX_FRAME, len(data) - offset):
        return None
    stored = struct.unpack_from('<I', data, offset + length - 4)[0]
    computed = zlib.crc32(data[offset:offset + length - 4], key_crc) & 0xFFFFFFFF
    frame = {
        'offset': offset, 'length': length, 'crc_ok': stored == computed,
        'key': None, 'value': None, 'type_id': None, 'deleted': False,
        'error': None, 'carved': False, 'truncated': False, 'encrypted': False,
    }
    reader = _Reader(data, offset + 4, offset + length - 4)
    try:
        frame['key'] = reader.key()
        if reader.remaining == 0:
            frame['deleted'] = True
        else:
            frame['type_id'] = data[reader.offset]
            frame['value'] = reader.value()
            if reader.remaining:
                frame['error'] = (f'{reader.remaining} byte(s) left unread after '
                                  f'the value')
    except (HiveError, IndexError, struct.error, UnicodeDecodeError) as err:
        frame['error'] = f'{type(err).__name__}: {err}'
    return frame


def _truncated_frame(data, offset):
    """What is present of a frame whose declared length runs past the file.

    A truncated box ends mid-frame, and the header and key come first, so the key
    of the write that was in flight is usually still readable.
    """
    if offset + 8 > len(data):
        return None
    length = struct.unpack_from('<I', data, offset)[0]
    if length < 8 or length <= len(data) - offset or length > _MAX_FRAME:
        return None
    frame = {
        'offset': offset, 'length': length, 'crc_ok': False, 'key': None,
        'value': None, 'type_id': None, 'deleted': False, 'carved': False,
        'truncated': True, 'encrypted': False,
        'error': (f'truncated: declares {length} bytes, '
                  f'{len(data) - offset} present'),
    }
    try:
        frame['key'] = _Reader(data, offset + 4, len(data)).key()
    except (HiveError, IndexError, struct.error, UnicodeDecodeError):
        pass
    return frame


def _carve(data, key_crc):
    """Every CRC-valid frame at any offset.

    A box has no magic bytes, so resynchronising after a damaged region depends
    entirely on the frame CRC. Only CRC-valid frames are returned, so this never
    invents one.
    """
    out, offset = [], 0
    while offset + 8 <= len(data):
        frame = _frame_at(data, offset, key_crc)
        if frame is not None and frame['crc_ok']:
            frame['carved'] = True
            out.append(frame)
            offset += frame['length']
            continue
        offset += 1
    return out


def _encrypted_chain(data, key_crc):
    """Every frame of an encrypted box, or None if this is not one.

    Hive seeds the frame CRC with a CRC of the encryption key, so an encrypted
    box fails every checksum while its keys stay in the clear. Reading it as a
    damaged box stops at the first frame and loses the rest of the key
    namespace, and decoding its ciphertext as a value invents a type id and a
    value that are not there.

    The test has to be stronger than "the first checksum failed", or a box with
    one corrupt frame reads as encrypted. The frame chain is followed by its
    declared lengths and accepted only when it lands exactly on the end of the
    file, every frame fails its checksum, and every key parses. Values are left
    undecoded, because they are ciphertext.
    """
    if len(data) < 8:
        return None
    frames, offset = [], 0
    while offset + 8 <= len(data):
        length = struct.unpack_from('<I', data, offset)[0]
        if length < 8 or length > min(_MAX_FRAME, len(data) - offset):
            return None
        stored = struct.unpack_from('<I', data, offset + length - 4)[0]
        computed = zlib.crc32(data[offset:offset + length - 4], key_crc) & 0xFFFFFFFF
        if stored == computed:
            return None                      # a readable frame: not encrypted
        try:
            reader = _Reader(data, offset + 4, offset + length - 4)
            key = reader.key()
        except (HiveError, IndexError, struct.error, UnicodeDecodeError):
            return None
        frames.append({
            'offset': offset, 'length': length, 'crc_ok': False, 'key': key,
            'value': None, 'type_id': None, 'deleted': False, 'carved': False,
            'truncated': False, 'encrypted': True,
            'error': 'value not decoded: the box appears to be encrypted',
        })
        offset += length
    if offset != len(data) or not frames:
        return None                          # the chain did not land on the end
    return frames


def read_frames(source, carve=False, key_crc=0):
    """Every frame in file order, superseded values and deletions included.

    ``source`` is a path or the bytes of a box. Each frame is a dict with
    offset, length, key, value, type_id, deleted, crc_ok, error, carved and
    truncated.

    The walk stops at the first frame whose checksum does not match, which is
    what tells a real frame from the tail of a partly overwritten file. Pass
    ``carve=True`` to scan the whole file for CRC-valid frames instead, which
    resynchronises past a damaged region and reads a fragment that does not start
    on a frame boundary. That is off by default: a scan can pick up a frame from
    an older, overwritten generation of the box, and the sequential walk is what
    the writer actually produced.

    ``key_crc`` is CRC32(SHA-256(key)) for an encrypted box and 0 otherwise.
    """
    if isinstance(source, (bytes, bytearray, memoryview)):
        data = bytes(source)
    else:
        with open(source, 'rb') as handle:
            data = handle.read()

    encrypted = _encrypted_chain(data, key_crc)
    if encrypted is not None:
        return encrypted

    frames, offset = [], 0
    while offset + 8 <= len(data):
        frame = _frame_at(data, offset, key_crc)
        if frame is None:
            truncated = _truncated_frame(data, offset)
            if truncated is not None:
                frames.append(truncated)
            break
        if not frame['crc_ok']:
            frames.append(frame)
            break
        frames.append(frame)
        offset += frame['length']

    if not carve:
        return frames

    by_offset = {f['offset']: f for f in frames}
    for frame in _carve(data, key_crc):
        existing = by_offset.get(frame['offset'])
        if existing is None or not existing['crc_ok']:
            by_offset[frame['offset']] = frame
    return [by_offset[o] for o in sorted(by_offset)]


def looks_encrypted(frames):
    """True when the box reads as encrypted rather than as damaged.

    Set by the frame-chain walk in ``read_frames``: every checksum failed, every
    key parsed, and the chain landed exactly on the end of the file. A box with
    one corrupt frame does not qualify.
    """
    return bool(frames) and all(f.get('encrypted') for f in frames)


def live_entries(frames):
    """``{key: value}`` using the last occurrence of each key.

    Deleted keys are dropped and frames that failed to parse are skipped, so this
    is what the app itself would read back.
    """
    out = {}
    for frame in frames:
        # A frame whose checksum failed is not trustworthy, so its value is not
        # live data however well it happened to parse.
        if (frame['key'] is None or frame['error'] is not None
                or not frame['crc_ok']):
            continue
        if frame['deleted']:
            out.pop(frame['key'], None)
        else:
            out[frame['key']] = frame['value']
    return out


def superseded_counts(frames):
    """``{key: how many of its frames were later replaced}``."""
    seen, out = {}, {}
    for frame in frames:
        key = frame['key']
        if (key is None or frame['error'] is not None or frame['deleted']
                or not frame['crc_ok']):
            continue
        if key in seen:
            out[key] = out.get(key, 0) + 1
        seen[key] = True
    return out


def displaced_counts(frames):
    """Value frames that are no longer live, split by what displaced them.

    Returns ``(overwritten, removed)``. A value frame is *overwritten* when a
    later frame writes that key again, and *removed* when a later frame deletes
    it. The two are different findings: "the value was replaced" and "the value
    was removed" mean different things in a report, and a count that merges them
    hands the reader the first when the truth is the second.

    Both are still in the file and still readable. They are the content a live
    read drops.
    """
    by_key = {}
    for index, frame in enumerate(frames):
        if (frame['key'] is None or not frame['crc_ok']
                or (frame['error'] is not None and not frame['deleted'])):
            continue
        by_key.setdefault(frame['key'], []).append((index, frame))

    overwritten = removed = 0
    for runs in by_key.values():
        for position, (_, frame) in enumerate(runs):
            if frame['deleted']:
                continue
            following = runs[position + 1:]
            if not following:
                continue                      # still the live value
            overwritten += not following[0][1]['deleted']
            removed += following[0][1]['deleted']
    return overwritten, removed


def hive_entries(path, carve=False):
    """``(live entries, superseded frame counts per key)`` for one box.

    The pairing LEAPP's artifact modules read.
    """
    frames = read_frames(path, carve=carve)
    return live_entries(frames), superseded_counts(frames)
